//! Prepare native text on the existing bounded reception worker, never the UI thread.
use mesh_talk_core::node::{HostReception, Node, SyncCategory};

pub(crate) struct NotificationPresentation {
    pub title: String,
    pub body: String,
}

pub(super) fn display_name(value: &str, fallback: &str) -> String {
    let value = clean(value);
    if value.is_empty() || (matches!(value.len(), 32 | 64) && value.bytes().all(|b| b.is_ascii_hexdigit())) {
        fallback.into()
    } else {
        value.chars().take(80).collect()
    }
}

fn clean(value: &str) -> String {
    value.chars().filter(|c| !c.is_control() && !matches!(c, '\u{202a}'..='\u{202e}' | '\u{2066}'..='\u{2069}'))
        .collect::<String>().split_whitespace().collect::<Vec<_>>().join(" ")
}

pub(crate) fn prepare_notification(node: &Node, receipt: &HostReception) -> NotificationPresentation {
    let language = node.account_preferences(SyncCategory::Appearance).into_iter()
        .find(|p| p.key == "language").and_then(|p| p.value).unwrap_or_default();
    let chinese = language.starts_with("zh") || language == "yue";
    let (unknown, group, protected) = if chinese { ("未知联系人", "群聊", "[受保护消息]") }
        else { ("Unknown contact", "Group chat", "[Protected message]") };
    let (device, account, supplied, channel) = match receipt {
        HostReception::DirectMessage(dm) => (dm.from.as_str(), dm.from_account.as_deref(), dm.from_name.as_str(), None),
        HostReception::ChannelMessage(msg) => (msg.from.as_str(), None, "", Some((msg.channel_id, msg.channel_name.as_str()))),
        HostReception::File(file) => (file.from.as_str(), None, "", file.is_channel.then_some((file.conv, ""))),
    };
    let (known_account, known_name) = node.peer_display_identity(device);
    let account = account.or(known_account.as_deref());
    let alias = account.and_then(|account| {
        node.account_preferences(SyncCategory::Contacts).into_iter()
            .find(|p| p.key == format!("favorite:{account}"))
            .and_then(|p| p.value)
            .and_then(|value| serde_json::from_str::<crate::favorites::FavoriteRecord>(&value).ok())
            .and_then(|record| record.custom_alias)
    });
    let profile = account.and_then(|account| node.account_display_name(account).ok().flatten());
    let sender = display_name(alias.as_deref().or(profile.as_deref()).or(known_name.as_deref()).unwrap_or(supplied), unknown);
    let body = match receipt {
        HostReception::DirectMessage(dm) => if dm.protection.is_some() { protected.into() } else { clean(&String::from_utf8_lossy(&dm.text)) },
        HostReception::ChannelMessage(msg) => if msg.protection.is_some() { protected.into() } else { clean(&String::from_utf8_lossy(&msg.text)) },
        HostReception::File(file) => attachment(&file.name, &file.mime, file.size, file.media, file.protection.is_some(), chinese),
    };
    if let Some((id, supplied)) = channel {
        let name = node.channel_display_name(id);
        NotificationPresentation { title: display_name(name.as_deref().unwrap_or(supplied), group), body: format!("{sender}: {body}") }
    } else {
        NotificationPresentation { title: sender, body }
    }
}

fn attachment(name: &str, mime: &str, size: u64, media: bool, protected: bool, chinese: bool) -> String {
    use mesh_talk_core::file::sticker;
    if protected { return if chinese { "[受保护消息]" } else { "[Protected message]" }.into(); }
    if sticker::valid_manifest(name, mime, size, media) {
        return if chinese { "[表情]" } else { "[Sticker]" }.into();
    }
    if media && mime.starts_with("image/") { return if chinese { "[图片]" } else { "[Photo]" }.into(); }
    if media && mime.starts_with("video/") { return if chinese { "[视频]" } else { "[Video]" }.into(); }
    let label = if chinese { "[文件]" } else { "[File]" };
    // Only show the basename; sender-controlled paths and control characters aren't UI.
    let name = clean(name.rsplit(['/', '\\']).next().unwrap_or_default());
    if name.is_empty() { label.into() } else { format!("{label} {name}") }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn notification_names_never_expose_raw_identifiers_or_control_characters() {
        assert_eq!(display_name(&"ab".repeat(16), "Unknown contact"), "Unknown contact");
        assert_eq!(display_name(&"ab".repeat(32), "Group chat"), "Group chat");
        assert_eq!(display_name(" \nAlice\u{202e} ", "Unknown"), "Alice");
        assert_eq!(display_name("王小明", "Unknown"), "王小明");
    }
    #[test]
    fn notification_attachments_preserve_type_intent_and_protection() {
        assert_eq!(attachment("secret.png", "image/png", 100, true, true, true), "[受保护消息]");
        assert_eq!(attachment("photo.png", "image/png", 100, true, false, true), "[图片]");
        assert_eq!(attachment("photo.png", "image/png", 100, false, false, false), "[File] photo.png");
        assert_eq!(attachment("../../report.pdf", "application/pdf", 100, false, false, true), "[文件] report.pdf");
        assert_eq!(attachment("movie.mp4", "video/mp4", 100, true, false, false), "[Video]");
        assert_eq!(attachment("mt-sticker-v1-YnVpbHRpbjp3YXZlCvCfkYs.png", "image/png", 100, true, false, true), "[表情]");
    }
}
